import { Component, OnInit } from '@angular/core';
import { Location } from '@angular/common';
import { ProductosService } from "../services/productos.service";

import { ActivatedRoute } from '@angular/router';

export interface Producto{
  id: number,
  nombre: string,
  marca: string,
  categoria: string,
  stock: number,
  valor_energetico: Float32Array,
  grasas: Float32Array,
  grasas_saturadas: Float32Array,
  hidratos_carbono: Float32Array,
  azucares: Float32Array,
  fibra: Float32Array,
  proteina: Float32Array,
  sal: Float32Array,
  precio_kg: Float32Array,
  ingerdientes: string,
  foto: string,
  precio: Float32Array
}

@Component({
  selector: 'app-pagina-producto',
  templateUrl: './pagina-producto.page.html',
  styleUrls: ['./pagina-producto.page.scss'],
})
export class PaginaProductoPage implements OnInit {

  productos: any;

  idProd: string = '';

  dispo: string = '';

  constructor( private route: ActivatedRoute, private productoService: ProductosService, private location: Location) {
   }

  ngOnInit() {

    this.route.paramMap.subscribe(params => {
      const id = params.get('id');
      
      if (id !== null) {
        this.idProd = id;
      } else {
        console.error('El parámetro "id" es nulo.');
      }
    });

   this.getProducto();

    
    
  }
  volverAtras() {
    this.location.back();
  }

  colorStock(disponibilidad: number): any{
    if (disponibilidad = 0) {
      this.dispo = 'Agotado';
      return { 'color': 'red' };
      
    } else {
      this.dispo = 'Disponible'
      return { 'color': 'green'  };
    }
  }

  getProducto(){
    this.productoService.getProductoId(this.idProd).subscribe( result => {
      this.productos = result.productos;
      console.log(this.productos);
    });
  }

}

<ion-content [fullscreen]="true" class="scroll">

  <ion-header collapse="condense" class="custom-header">
    <ion-toolbar class="custom-toolbar">
      <button class="volver-atras" (click)="volverAtras()">
        <ion-icon name="chevron-back-outline"></ion-icon>
        Volver atrás</button>
    </ion-toolbar>
  </ion-header>
  
  <div class="content-producto" *ngIf="productos">
    <div class="imagen">
      <img [src]="'assets/images/' + productos.id + '.jpg'" alt="Product Image" />
      <button>
        <ion-icon class="add" name="add-circle-outline"></ion-icon>
      </button>
    </div>

    <div class="info-producto" >
      <h2 class="nombre_producto">{{ productos.nombre }}</h2>
      <div class="disponibilidad">
        <ion-icon name="ellipse" id="divStock" [ngStyle]="colorStock(productos.stock)" class></ion-icon> 
        <p class="dispo">{{dispo}}</p>
      </div>
      <div class="precio">
        <p class="precio_producto">{{ productos.precio }}€</p>
        <p class="precio_kg_producto">{{ productos.precio_kg }}€/kg</p>
        <button class="localizar" [routerLink]="['/tabs/tab3']">
          Localizar
          <ion-icon name="location-outline"></ion-icon>
        </button>
      </div>
     
      
    </div>

    <div class="ingredientes">
      <h3>Ingredientes</h3>
      <p>{{ productos.ingredientes }}</p>
    </div>
    
    <div class="valores_nutricionales">
      <h3>Valores Nutricionales</h3>
      <p>Valor energético: {{productos.valor_energetico}} kcal</p>
      <p>Grasas {{productos.grasas}} g</p>
      <p>de las cuales saturadas {{productos.grasas_saturadas}} g</p>
      <p>Hidratos de carbono {{productos.hidratos_carbono}} g</p>
      <p>de los cuales azúcares {{productos.azucares}} g</p>
      <p>Fibra alimentaria {{productos.fibra}} g</p>
      <p>Proteínas {{productos.proteina}} g</p>
      <p>Sal {{productos.sal}} g</p>

      <!--<app-chart [chartData]="doughnutChartData"></app-chart>-->

    </div>


  </div>


   <div class="menu-inferior">
    <button [routerLink]="['/tabs/tab1']">
      <ion-icon class="icono-menu" name="list-circle-outline"></ion-icon>
    </button>
    <button [routerLink]="['/tabs/tab2']">
      <ion-icon class="icono-menu" name="chatbubbles-outline"></ion-icon>
    </button>
    <button [routerLink]="['/tabs/tab3']">
      <ion-icon class="icono-menu" name="person-circle-outline"></ion-icon>
    </button>
  </div>

</ion-content>
